// ==========================================
// HELPERS FOR APPENDING ADDITIONAL DATA FILES
// ==========================================
window.addSpanishPhrases = function addSpanishPhrases(items) {
  if (!Array.isArray(items)) return;
  window.SPANISH_CLINIC_PHRASES.push(...items);
  if (window.DuoPA && typeof window.DuoPA.refreshData === 'function') {
    window.DuoPA.refreshData();
  }
};

window.addQuestions = function addQuestions(items) {
  if (!Array.isArray(items)) return;
  window.EXPANDED_QUESTION_BANK.push(...items);
  if (window.DuoPA && typeof window.DuoPA.refreshData === 'function') {
    window.DuoPA.refreshData();
  }
};
